DO $$ BEGIN
 IF EXISTS (SELECT c.name FROM channels c JOIN heyroute_channels s ON c.name=s.payload->>'name' GROUP BY c.name HAVING count(*)>1) THEN
  RAISE EXCEPTION 'duplicate HeyRoute channel names';
 END IF;
END $$;
-- Catalog metadata is inserted only for new models; other vendors retain ownership.
INSERT INTO models (model_name,description,tags,endpoints,kind,capabilities,status,sync_official,created_time,updated_time,name_rule,params_def,pricing_config)
SELECT payload->>'model_name','HeyRoute model','heyroute',(payload->'endpoints')::text,payload->>'kind',
 (payload->'capabilities')::text,1,0,extract(epoch from now())::bigint,extract(epoch from now())::bigint,0,
 (payload->'params_def')::text,NULLIF((payload->'pricing_config')::text,'{}')
FROM heyroute_models s WHERE NOT EXISTS (SELECT 1 FROM models m WHERE m.model_name=s.payload->>'model_name' AND deleted_at IS NULL);
INSERT INTO channels (name,type,"group",models,model_mapping,status,base_url,key,created_time,priority,weight,tag,setting,test_model,auto_ban)
SELECT payload->>'name',1,'default',payload->>'models',(payload->'mapping')::text,2,'https://heyroute.ai','',
 extract(epoch from now())::bigint,100,100,payload->>'name',(payload->'setting')::text,payload->>'test_model',1
FROM heyroute_channels s WHERE NOT EXISTS (SELECT 1 FROM channels c WHERE c.name=s.payload->>'name');
UPDATE channels c SET models=s.payload->>'models',model_mapping=(s.payload->'mapping')::text,
 setting=(COALESCE(NULLIF(c.setting,''),'{}')::jsonb || (s.payload->'setting'))::text,
 base_url='https://heyroute.ai',test_model=s.payload->>'test_model'
FROM heyroute_channels s WHERE c.name=s.payload->>'name';
-- Retire stale routing entries without deleting their records.
UPDATE abilities a SET enabled=false FROM channels c, heyroute_channels s
WHERE a.channel_id=c.id AND c.name=s.payload->>'name'
 AND (a."group"<>c."group" OR NOT (a.model=ANY(string_to_array(s.payload->>'models',','))));
INSERT INTO abilities ("group",model,channel_id,enabled,priority,weight,tag)
SELECT c."group",m,c.id,c.status=1 AND length(btrim(c.key))>0,c.priority,c.weight,c.tag
FROM channels c JOIN heyroute_channels s ON c.name=s.payload->>'name'
CROSS JOIN LATERAL unnest(string_to_array(s.payload->>'models',',')) m
ON CONFLICT ("group",model,channel_id) DO UPDATE SET enabled=abilities.enabled AND excluded.enabled,priority=excluded.priority,weight=excluded.weight,tag=excluded.tag;
