ON CONFLICT (key) DO UPDATE SET value=('{"gpt-image-2":0.125,"flux-klein-2":0.375,"grok-imagine-image":0.125,"gemini-3-pro-image-preview":0.2,"gemini-3.1-flash-image-preview":0.2,"grok-video":0.07500000000000001,"grok-imagine-video":0.375,"grok-imagine-1.5-video":0.5625,"minimax-h3-quantized-768p":0.10500000000000001,"minimax-h3-original-768p":0.26249999999999996,"minimax-h3-original-1080p":0.39375000000000004,"minimax-h3-original-cf-2k":0.39375000000000004,"minimax-h3":0.28125,"seedance-2.5":1.72125,"seedance-2.0":0.5625,"seedance-2.0-fast":0.5625}'::jsonb || COALESCE(NULLIF(options.value,''),'{}')::jsonb)::text;
DO $$ BEGIN
 IF (SELECT count(*) FROM channels c JOIN heyroute_channels s ON c.name=s.payload->>'name')<>7 THEN
  RAISE EXCEPTION 'expected seven HeyRoute channels';
 END IF;
 IF (SELECT count(*) FROM abilities a JOIN channels c ON a.channel_id=c.id JOIN heyroute_channels s ON c.name=s.payload->>'name'
 WHERE a.model=ANY(string_to_array(s.payload->>'models',',')) AND (NOT a.enabled OR (c.status=1 AND length(btrim(c.key))>0)))<>31 THEN
  RAISE EXCEPTION 'HeyRoute ability invariant failed';
 END IF;
END $$;
COMMIT;
